:root {
  color-scheme: light;
  --canvas: var(--sya-canvas, #eef1ed);
  --surface: var(--sya-surface, #fcfdfb);
  --surface-muted: var(--sya-surface-muted, #e2e6e1);
  --text: var(--sya-text, #191b19);
  --text-secondary: var(--sya-text-secondary, #59605b);
  --border: var(--sya-border, #d9ddd9);
  --primary: var(--sya-primary, #252725);
  --primary-hover: var(--sya-primary-hover, #343734);
  --primary-foreground: var(--sya-primary-foreground, #f8faf8);
  --success: var(--sya-success, #18794e);
  --success-foreground: var(--sya-success-foreground, #ffffff);
  --success-surface: var(--sya-success-surface, #e7f6ec);
  --success-surface-foreground: var(--sya-success-surface-foreground, #17653f);
  --warning: var(--sya-warning, #946200);
  --warning-foreground: var(--sya-warning-foreground, #ffffff);
  --warning-surface: var(--sya-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #6b4600);
  --danger: var(--sya-danger, #b42318);
  --danger-foreground: var(--sya-danger-foreground, #ffffff);
  --danger-surface: var(--sya-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #8f1d14);
  --focus: var(--sya-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--sya-canvas, #121412);
    --surface: var(--sya-surface, #1a1d1a);
    --surface-muted: var(--sya-surface-muted, #232623);
    --text: var(--sya-text, #f1f3f0);
    --text-secondary: var(--sya-text-secondary, #afb5b0);
    --border: var(--sya-border, #373b37);
    --primary: var(--sya-primary, #ecefeb);
    --primary-hover: var(--sya-primary-hover, #ffffff);
    --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
    --success: var(--sya-success, #62c98f);
    --success-foreground: var(--sya-success-foreground, #092416);
    --success-surface: var(--sya-success-surface, #173526);
    --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
    --warning: var(--sya-warning, #e9ad45);
    --warning-foreground: var(--sya-warning-foreground, #291900);
    --warning-surface: var(--sya-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
    --danger: var(--sya-danger, #ff716b);
    --danger-foreground: var(--sya-danger-foreground, #260503);
    --danger-surface: var(--sya-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
    --focus: var(--sya-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--sya-canvas, #121412);
  --surface: var(--sya-surface, #1a1d1a);
  --surface-muted: var(--sya-surface-muted, #232623);
  --text: var(--sya-text, #f1f3f0);
  --text-secondary: var(--sya-text-secondary, #afb5b0);
  --border: var(--sya-border, #373b37);
  --primary: var(--sya-primary, #ecefeb);
  --primary-hover: var(--sya-primary-hover, #ffffff);
  --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
  --success: var(--sya-success, #62c98f);
  --success-foreground: var(--sya-success-foreground, #092416);
  --success-surface: var(--sya-success-surface, #173526);
  --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
  --warning: var(--sya-warning, #e9ad45);
  --warning-foreground: var(--sya-warning-foreground, #291900);
  --warning-surface: var(--sya-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
  --danger: var(--sya-danger, #ff716b);
  --danger-foreground: var(--sya-danger-foreground, #260503);
  --danger-surface: var(--sya-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
  --focus: var(--sya-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .sya-code-source .shiki,
html[data-theme="dark"] .sya-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .sya-code-source .shiki,
  html:not([data-theme="light"]) .sya-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { CodeBlockView } from "./code-block-view";

export interface CodeBlockProps {
  code: string;
  language?: "bash" | "css" | "html" | "javascript" | "json" | "tsx" | "typescript";
  filename?: string;
  variant?: "standalone" | "embedded";
  className?: string;
  previewLines?: number;
}

type ShikiModule = typeof import("shiki");
type Highlighter = Awaited<ReturnType<ShikiModule["createHighlighter"]>>;

let highlighterPromise: Promise<Highlighter> | undefined;

function getHighlighter() {
  highlighterPromise ??= import("shiki").then(({ createHighlighter }) => createHighlighter({
    themes: ["github-light", "github-dark"],
    langs: ["bash", "css", "html", "javascript", "json", "tsx", "typescript"],
  }));

  return highlighterPromise;
}

export function CodeBlock({
  code,
  language = "tsx",
  filename,
  variant = "standalone",
  className,
  previewLines = 18,
}: CodeBlockProps) {
  const source = useMemo(() => code.trim(), [code]);
  const [highlighted, setHighlighted] = useState<{ source: string; html: string }>();
  const html = highlighted?.source === source ? highlighted.html : plainCodeToHtml(source);

  useEffect(() => {
    let active = true;

    getHighlighter().then((highlighter) => {
      if (!active) return;
      setHighlighted({
        source,
        html: withLineNumbers(highlighter.codeToHtml(source, {
          lang: language,
          themes: { light: "github-light", dark: "github-dark" },
          defaultColor: false,
        })),
      });
    });

    return () => {
      active = false;
    };
  }, [language, source]);

  return (
    <CodeBlockView
      className={className}
      code={source}
      filename={filename}
      html={html}
      lineCount={source.split("\n").length}
      previewLines={Math.max(1, Math.floor(previewLines))}
      variant={variant}
    />
  );
}

function plainCodeToHtml(code: string) {
  const lines = escapeHtml(code).split("\n").map(
    (line, index) => `<span class="line"><span aria-hidden="true" class="line-number">${index + 1}</span>${line || " "}</span>`,
  ).join("");

  return `<pre class="shiki" tabindex="0"><code>${lines}</code></pre>`;
}

function escapeHtml(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function withLineNumbers(html: string) {
  let line = 0;

  return html.replaceAll(
    '<span class="line">',
    () =>
      `<span class="line"><span aria-hidden="true" class="line-number">${++line}</span>`,
  );
}

"use client";

import type { CSSProperties } from "react";
import { useId, useLayoutEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { Check, ChevronDown, ChevronUp, Copy, FileCode2 } from "lucide-react";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

interface CodeBlockViewProps {
  code: string;
  html: string;
  lineCount: number;
  previewLines: number;
  filename?: string;
  variant: "standalone" | "embedded";
  className?: string;
}

export function CodeBlockView({
  code,
  html,
  lineCount,
  previewLines,
  filename,
  variant,
  className,
}: CodeBlockViewProps) {
  const [copied, setCopied] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [contentHeight, setContentHeight] = useState<number>();
  const sourceRef = useRef<HTMLDivElement>(null);
  const sourceId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const remainingLines = Math.max(lineCount - previewLines, 0);
  const canExpand = remainingLines > 0;
  const classes = [
    "mt-3 overflow-hidden rounded-[18px] border border-[var(--border)] bg-[var(--surface-muted)]",
    variant === "embedded" && "mt-0 rounded-none border-0",
    className,
  ].filter(Boolean).join(" ");
  const collapsedHeight = previewLines * 21 + 24;
  const sourceStyle = {
    "--code-preview-height": `${previewLines * 1.75}em`,
  } as CSSProperties;

  useLayoutEffect(() => {
    const source = sourceRef.current;
    const content = source?.firstElementChild;
    if (!source || !content) return;

    const measure = () => setContentHeight(source.scrollHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(content);
    return () => observer.disconnect();
  }, [html]);

  const copyCode = async () => {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1600);
  };

  return (
    <div className={classes}>
      <div className="flex min-h-[42px] items-center border-b border-[var(--border)] bg-[var(--surface)]">
        <div className="flex min-w-0 flex-1 items-center gap-2 overflow-hidden px-3.5 py-2.5 font-mono text-[11px] leading-[17px] text-ellipsis whitespace-nowrap text-[var(--text-secondary)] [&>span]:overflow-hidden [&>span]:text-ellipsis">
          <FileCode2 aria-hidden="true" size={16} />
          <span>{filename ?? "Code"}</span>
        </div>
        <Button
          aria-label="Copy code"
          className="mr-1.5 gap-[7px] whitespace-nowrap"
          onClick={copyCode}
          size="small"
          variant="text"
        >
          {copied ? <Check aria-hidden="true" size={15} /> : <Copy aria-hidden="true" size={15} />}
          {copied ? "Copied" : "Copy"}
        </Button>
      </div>
      <motion.div
        ref={sourceRef}
        className={["sya-code-source overflow-hidden [&_.shiki]:m-0 [&_.shiki]:overflow-x-auto [&_.shiki]:overflow-y-hidden [&_.shiki]:bg-[var(--surface-muted)] [&_.shiki]:p-2.5 [&_.shiki]:font-mono [&_.shiki]:text-xs [&_.shiki]:leading-[1.75] [&_.shiki]:[tab-size:2] [&_.shiki]:whitespace-normal [&_.shiki]:text-[var(--shiki-light)] [&_.shiki_span]:text-[var(--shiki-light)] [&_.shiki:focus-visible]:outline-2 [&_.shiki:focus-visible]:outline-[var(--focus)] [&_.shiki:focus-visible]:outline-offset-[-3px] [&_.line]:relative [&_.line]:block [&_.line]:min-h-[1.75em] [&_.line]:pl-10 [&_.line]:whitespace-pre [&_.line-number]:absolute [&_.line-number]:top-0 [&_.line-number]:left-0 [&_.line-number]:w-[1.875rem] [&_.line-number]:text-right [&_.line-number]:text-[var(--text-secondary)] [&_.line-number]:select-none max-[760px]:[&_.shiki]:px-2 max-[760px]:[&_.shiki]:py-2 max-[760px]:[&_.line]:pl-9", variant === "embedded" && "[&_.shiki]:min-h-[250px]"].join(" ")}
        data-collapsed={canExpand && !expanded || undefined}
        id={sourceId}
        style={sourceStyle}
        initial={false}
        animate={{ height: canExpand ? expanded ? contentHeight ?? "auto" : collapsedHeight : "auto" }}
        transition={reduceMotion
          ? { duration: 0.01 }
          : { duration: motionTokens.duration.standard, ease: motionTokens.ease.standard }}
        dangerouslySetInnerHTML={{ __html: html }}
      />
      {canExpand ? (
        <div className="flex min-h-9 items-center justify-center border-t border-[var(--border)] bg-[var(--surface)]">
          <Button
            aria-controls={sourceId}
            aria-expanded={expanded}
            className="gap-[7px] text-[var(--text-secondary)]"
            onClick={() => setExpanded((current) => !current)}
            size="small"
            variant="text"
          >
            {expanded
              ? <><ChevronUp aria-hidden="true" size={15} /> Show fewer lines</>
              : <><ChevronDown aria-hidden="true" size={15} /> Show all ${lineCount} lines</>}
          </Button>
        </div>
      ) : null}
    </div>
  );
}
